    for (int i = 3; i <= n; i += 2) is_prime[i] = 1;
    for (int i = 3; (i * i) <= n; i += 2)
        if (is_prime[i])
            for (int j = i * i; j <= n; j += (i + i)) is_prime[j] = 0;
    is_prime[1] = 0;
    is_prime[2] = 1;
    primes.push_back(2);
    for (int i = 3; i <= n; i += 2)
        if (is_prime[i]) primes.push_back(i);
}
long long SODFormula(long long n)
{
    long long ans = 1;
    for (auto p : primes) {
        if (1LL * p * p > n) break;
        if (n % p == 0) {
            long long pw = p;
            while (n % p == 0) { pw *= p; n /= p; }
            ans *= ((pw - 1) / (p - 1));
        }
    }
    if (n > 1) ans *= (n + 1);
    return ans;
}

int main()
{
    int t;
    cin >> t;
    sieve(999);
    while (t--) {
        long long n;
        cin >> n;
        cout << SODFormula(n) << endl;
    }
    return 0;
}

